    return(
        <section>
            <label htmlFor="title">Title</label>
            <input id="title" placeholder="Enter Title" type="text"/>
            <label htmlFor="date">Title</label>
            <input id="date" placeholder="Enter Date" type="date"/>
            <label htmlFor="director">Title</label>
            <input id="director" placeholder="Enter director Name" type="text"/>
        </section>
    )
}


export default Form;
